mapper.select:
/* isry.itgcm.linkmng.outsd.mapper.LinkTrprRqstMapper.selectCaseMngHisList */ WITH VW_TRPR_INFO_NO AS ( SELECT T1.TRPR_INFO_NO FROM SEA200 T1 /* 대상자정보 */ WHERE 1 = 1 AND T1.INDV_IDNTFC_NO = ( SELECT X.INDV_IDNTFC_NO FROM SEA200 X /* 대상자정보 */ , SCA300 Y /* 개인정보 */ WHERE X.TRPR_INFO_NO = #{TRPR_INFO_NO} AND X.INDV_IDNTFC_NO = Y.INDV_IDNTFC_NO ) UNION SELECT T1.TRPR_INFO_NO FROM ( SELECT X.RQST_TRPR_INFO_NO AS TRPR_INFO_NO /* 의뢰대상자정보번호 */ FROM SEB400 X /* 서비스제공의뢰 */ WHERE X.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */
UNION SELECT Z.RCPT_TRPR_INFO_NO /* 접수대상자정보번호 */ FROM SEB400 Y /* 서비스제공의뢰 */ , SEB420 Z /* 서비스제공접수 */ WHERE Y.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */ AND Y.SRVC_PVSN_RQST_NO = Z.SRVC_PVSN_RQST_NO /* 서비스제공의뢰번호 */ ) T1 , SEA200 T2 /* 대상자정보 */ WHERE T1.TRPR_INFO_NO = T2.TRPR_INFO_NO UNION SELECT #{TRPR_INFO_NO} FROM DUAL )
SELECT T1.CASE_MNG_NO , T1.CASE_MNG_ODRNO , T1.CASE_MNG_BGNG_YMD , T1.CASE_MNG_TRMN_YMD , T1.PRGRS_STTS_SE_NM , T1.TKCG_INST_ID , T1.TKCG_INST_NM , T1.PIC_NM , T1.UNT_TASKWK_SE_CD , T1.UNT_TASKWK_SE_NM , MAX(T1.LAST_MDFCN_DT) AS LAST_MDFCN_DT , T1.WRD_TELNO AS PIC_CTTPC FROM ( SELECT DISTINCT T3.TRPR_NM_ENCPT AS TRPR_FLNM /* 대상자성명 */ , T4.RRNO_ENCPT AS TRPR_RRNO /* 대상자주민등록번호 */ , T2.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T2.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T1.CASE_BGNG_YMD AS CASE_MNG_BGNG_YMD /* 사례관리 시작일자 */ , T1.CASE_TRMN_YMD AS CASE_MNG_TRMN_YMD /* 사례관리 종결일자 */ , '' AS TRPR_TYPE_SE_CD /* 대상자유형코드 */ , '' AS TRPR_TYPE_SE_NM /* 대상자유형명 */ , T2.CASE_PRGRS_STTS_SE_CD AS PRGRS_STTS_SE_CD /* 진행상태코드 */ , ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = 'CASE_PRGRS_STTS_TYPE_SE_CD' AND X.CMMNS_CD_VALUE = ( SELECT UP_CMMNS_CD_VALUE FROM SAC100 X WHERE X.CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND X.CMMNS_CD_VALUE = T2.CASE_PRGRS_STTS_SE_CD ) ) AS PRGRS_STTS_SE_NM /* 진행상태명 */ /* 진행상태명 */ , T2.PIC_INST_NO AS TKCG_INST_ID /* 담당기관ID */ , ( SELECT X.INST_NM FROM SAA000 X /* 통합기관 */ WHERE X.DEL_YN = 'N' AND X.INST_NO = T2.PIC_INST_NO ) AS TKCG_INST_NM /* 담당기관명 */ , C##RG.DEC_B64(T5.FLNM_ENCPT) AS PIC_NM /* 담당자명 */ , T5.WRD_TELNO AS WRD_TELNO /* 유선전화번호 */ , T5.MBL_TELNO_ENCPT AS MBL_TELNO /* 휴대전화번호암호화 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , ( SELECT X.CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND X.CMMNS_CD_VALUE = T1.UNT_TASKWK_SE_CD ) AS UNT_TASKWK_SE_NM /* 단위업무구분명 */ , TO_CHAR(T2.LAST_MDFCN_DT,'YYYYMMDD') AS LAST_MDFCN_DT /* 수정일자 */ , T2.CASE_MNG_HSTR_NO AS CASE_MNG_HSTR_NO /* 사례관리이력번호 */ , '' AS CASE_MNG_TYPE_ID /* 사례관리유형ID */ , '' AS CASE_MNG_STD_TASKWK_PRCS_ID /* 사례관리표준업무처리ID */ , '' AS CASE_MNG_DTL_SE_CD /* 사례관리상세구분코드 */ FROM SEB100 T1 /* 사례기본 */ , SEB110 T2 /* 사례관리이력 */ , SEA200 T3 /* 대상자정보 */ , SCA300 T4 /* 개인정보 */ , SCA100 T5 /* 종사자 */ WHERE T1.CASE_MNG_NO = T2.CASE_MNG_NO AND T1.CASE_MNG_ODRNO = T2.CASE_MNG_ODRNO AND T2.TRPR_INFO_NO = T3.TRPR_INFO_NO (+) AND T3.INDV_IDNTFC_NO = T4.INDV_IDNTFC_NO(+) AND T2.CASE_PIC_NO = T5.ENFSN_NO (+) AND T2.TRPR_INFO_NO IN ( SELECT X.TRPR_INFO_NO FROM VW_TRPR_INFO_NO X ) AND T2.CASE_MNG_HSTR_NO IN ( SELECT CASE_MNG_HSTR_NO FROM ( /* 1개사례기준 최근 한건만(기준 : 사례관리번호/차수)*/ SELECT ROW_NUMBER () OVER(PARTITION BY X.CASE_PRGRS_STTS_SE_CD ORDER BY X.FRST_REG_DT DESC) RNUM , X.CASE_MNG_HSTR_NO FROM SEB110 X WHERE X.CASE_MNG_NO = T1.CASE_MNG_NO AND X.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO ) WHERE RNUM = 1 ) ) T1 GROUP BY T1.CASE_MNG_NO , T1.CASE_MNG_ODRNO , T1.CASE_MNG_BGNG_YMD , T1.CASE_MNG_TRMN_YMD , T1.PRGRS_STTS_SE_NM , T1.TKCG_INST_ID , T1.TKCG_INST_NM , T1.PIC_NM , T1.UNT_TASKWK_SE_CD , T1.UNT_TASKWK_SE_NM , T1.WRD_TELNO ORDER BY T1.CASE_MNG_BGNG_YMD

/* isry.itgcm.linkmng.outsd.mapper.LinkTrprRqstMapper.selectSrvcPvsnHisList */ WITH VW_TRPR_INFO_NO AS ( SELECT T1.TRPR_INFO_NO FROM ( SELECT X.RQST_TRPR_INFO_NO AS TRPR_INFO_NO /* 의뢰대상자정보번호 */ FROM SEB400 X /* 서비스제공의뢰 */ WHERE X.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */
UNION SELECT Z.RCPT_TRPR_INFO_NO /* 접수대상자정보번호 */ FROM SEB400 Y /* 서비스제공의뢰 */ , SEB420 Z /* 서비스제공접수 */ WHERE Y.RQST_TRPR_INFO_NO = #{TRPR_INFO_NO} /* 의뢰대상자정보번호 */ AND Y.SRVC_PVSN_RQST_NO = Z.SRVC_PVSN_RQST_NO /* 서비스제공의뢰번호 */ ) T1 , SEA200 T2 /* 대상자정보 */ WHERE T1.TRPR_INFO_NO = T2.TRPR_INFO_NO UNION SELECT #{TRPR_INFO_NO} FROM DUAL )
SELECT DISTINCT CASE WHEN T6.INDV_IDNTFC_NO IS NULL THEN NVL(T6.TRPR_NM_ENCPT, T7.FLNM_ENCPT) ELSE T7.FLNM_ENCPT END AS TRPR_FLNM /* 대상자성명 */ , T7.RRNO_ENCPT AS TRPR_RRNO /* 대상자주민등록번호 */ , '' AS TRPR_SPCL_INFO_CN /* 대상자특화정보 */ , T1.SRVC_PVSN_NO AS PVSN_SRVC_ID /* 제공서비스ID */ , T4.PVSN_RESRCE_NM AS PVSN_SRVC_NM /* 제공서비스명 */ , T4.RSFR_INST_NO AS PVSN_MBD_ID /* 제공주체ID */ , T5.INST_NM AS PVSN_MBD_NM /* 제공주체명 */ , T1.SRVC_PVSN_BGNG_YMD AS SRVC_BGNG_YMD /* 서비스시작일자 */ , T1.SRVC_PVSN_END_YMD AS SRVC_END_YMD /* 서비스종료일자 */ , T4.RESRCE_SE_CD AS SRVC_PVSN_SE_CD /* 서비스제공구분코드 */ , '' AS SRVC_PVSN_CYCL_SE_CD /* 서비스제공주기코드 */ , '' AS SRVC_PVSN_CYCL_SE_NM /* 서비스제공주기명 */ , T1.SRVC_PVSN_CN AS SRVC_BNF_CN /* 서비스수혜내용 */ , T1.SRVC_PVSN_CN AS SRVC_PVSN_CN /* 서비스제공내용 */ , C##RG.DEC_B64(T8.FLNM_ENCPT) AS SRVC_PVSN_PIC_NM /* 서비스제공담당자명 */ , T8.WRD_TELNO AS WRD_TELNO /* 서비스제공담당자유선전화번호 */ , T8.MBL_TELNO_ENCPT AS MBL_TELNO /* 서비스제공담당자휴대전화번호 */ FROM SEB500 T1 /* 서비스제공 */ , SEB510 T2 /* 서비스제공대상자 */ , SEB100 T3 /* 사례기본 */ , SDA100 T4 /* 자원기본 */ , SAA000 T5 /* 통합기관 */ , SEA200 T6 /* 대상자정보 */ , SCA300 T7 /* 개인정보 */ , SCA100 T8 /* 종사자 */ WHERE T1.SRVC_PVSN_NO = T2.SRVC_PVSN_NO AND T1.RESRCE_NO = T2.RESRCE_NO AND T1.RESRCE_NO = T4.RESRCE_NO AND T2.CASE_MNG_NO = T3.CASE_MNG_NO AND T2.CASE_MNG_ODRNO = T3.CASE_MNG_ODRNO AND T3.TRPR_INFO_NO IN ( SELECT X.TRPR_INFO_NO FROM VW_TRPR_INFO_NO X ) AND T1.PIC_NO = T8.ENFSN_NO (+) AND T4.RSFR_INST_NO = T5.INST_NO (+) AND T3.TRPR_INFO_NO = T6.TRPR_INFO_NO (+) AND T6.INDV_IDNTFC_NO = T7.INDV_IDNTFC_NO(+)

SELECT A.RQST_YMD , B.RCPT_YMD , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RCPT_SE_CD' AND CMMNS_CD_VALUE = B.RCPT_SE_CD) AS RCPT_SE_NM , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 C WHERE C.ENFSN_NO = A.CLINT_NO) AS CLINT_NM -- 의뢰자 , (SELECT C.INST_NM FROM SAA000 C WHERE A.RQST_INST_NO = C.INST_NO) AS RQST_INST_NM -- 의뢰기관 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 C WHERE C.ENFSN_NO = A.CLR_NO) AS CLR_NM -- 접수자 , (SELECT C.INST_NM FROM SAA000 C WHERE A.RCPT_INST_NO = C.INST_NO) AS RCPT_INST_NM -- 접수기관 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RJCT_CS_SE_CD' AND CMMNS_CD_VALUE = B.RJCT_CS_SE_CD) AS RJCT_CS_SE_NM , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RQST_UNT_TASKWK_SE_CD' AND CMMNS_CD_VALUE = A.RQST_UNT_TASKWK_SE_CD ) AS RQST_UNT_TASKWK_SE_NM , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RCPT_UNT_TASKWK_SE_CD' AND CMMNS_CD_VALUE = A.RCPT_UNT_TASKWK_SE_CD ) AS RCPT_UNT_TASKWK_SE_NM FROM SEB400 A, SEB420 B WHERE A.SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND A.RQST_TRPR_INFO_NO IN (
(SELECT TRPR_INFO_NO FROM SEA200 WHERE INDV_IDNTFC_NO = #{INDV_IDNTFC_NO})
#{TRPR_INFO_NO}
)

