mapper.select:
SELECT  MIN(SRVC_PVSN_RQST_NO) KEEP(DENSE_RANK FIRST ORDER BY FRST_REG_DT DESC) AS SRVC_PVSN_RQST_NO
FROM SEB400
WHERE RQST_TRPR_INFO_NO = #{RQST_TRPR_INFO_NO}

/*getSrvcPvsnRqstData : 연계의뢰 상세*/ SELECT A.SRVC_PVSN_RQST_NO , C.PVSN_RESRCE_NM , A.RESRCE_NO , A.HPE_SRVC_YN , A.RQST_UNT_TASKWK_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RQST_UNT_TASKWK_SE_CD' AND D.CMMNS_CD_VALUE = A.RQST_UNT_TASKWK_SE_CD ) AS RQST_UNT_TASKWK_SE_NM , A.RCPT_RQST_COURS_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND D.CMMNS_CD_VALUE = A.RCPT_RQST_COURS_SE_CD ) AS RCPT_RQST_COURS_SE_NM , A.RQST_YMD , A.CLINT_NO , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 C WHERE C.ENFSN_NO = A.CLINT_NO) AS CLINT_NM , A.RQST_INST_NO , (SELECT C.INST_NM FROM SAA000 C WHERE A.RQST_INST_NO = C.INST_NO) AS RQST_INST_NM , A.RQST_CS_CN , A.PRNMNT_USE_BGNG_YMD , A.PRNMNT_USE_BGNG_HR , A.PRNMNT_USE_END_YMD , A.PRNMNT_USE_END_HR , A.RCPT_UNT_TASKWK_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RCPT_UNT_TASKWK_SE_CD' AND D.CMMNS_CD_VALUE = A.RCPT_UNT_TASKWK_SE_CD ) AS RCPT_UNT_TASKWK_SE_NM , A.CLR_NO , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 C WHERE C.ENFSN_NO = A.CLR_NO) AS CLR_NM
, (SELECT WRD_TELNO FROM SCA100 C WHERE C.ENFSN_NO = A.CLR_NO) AS CLR_WRD_TELNO , (SELECT C##RG.DEC_B64(MBL_TELNO_ENCPT) FROM SCA100 C WHERE C.ENFSN_NO = A.CLR_NO) AS CLR_MBL_TELNO_ENCPT
, A.RCPT_INST_NO , (SELECT C.INST_NM FROM SAA000 C WHERE A.RCPT_INST_NO = C.INST_NO) AS RCPT_INST_NM , A.RQST_TRPR_INFO_NO , (SELECT C##RG.DEC_B64(D.TRPR_NM_ENCPT) FROM SEA200 D WHERE D.TRPR_INFO_NO = A.RQST_TRPR_INFO_NO) AS RQST_TRPR_INFO_NM , (SELECT D.INDV_IDNTFC_NO FROM SEA200 D WHERE D.TRPR_INFO_NO = A.RQST_TRPR_INFO_NO) AS INDV_IDNTFC_NO , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , A.RQST_APLY_YN , A.RQST_DTL_CN , A.LINK_TYPE_SE_CD , (SELECT RCPT_SE_CD FROM (SELECT * FROM SEB420 ORDER BY RCPT_SN DESC) V WHERE ROWNUM = 1 AND V.SRVC_PVSN_RQST_NO = A.SRVC_PVSN_RQST_NO ) AS RCPT_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'LINK_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = A.LINK_TYPE_SE_CD ) AS LINK_TYPE_SE_NM , A.ATFINO , A.TRMN_PRCS_YN FROM SEB400 A LEFT JOIN SEB500 B ON A.RESRCE_NO = B.RESRCE_NO AND A.SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO LEFT JOIN SDA100 C ON A.RESRCE_NO = C.RESRCE_NO WHERE A.SRVC_PVSN_RQST_NO = #{SRVC_PVSN_RQST_NO}

mapper.insert:
INSERT INTO SEB401 (
     MDFCN_DT
    ,SRVC_PVSN_RQST_NO
    , DATAA_CHG_SE_CD
    , RESRCE_NO
    , HPE_SRVC_YN
    , RQST_UNT_TASKWK_SE_CD
    , RCPT_RQST_COURS_SE_CD
    , RQST_YMD
    , CLINT_NO
    , RQST_INST_NO
    , RQST_CS_CN
    , PRNMNT_USE_BGNG_YMD
    , PRNMNT_USE_BGNG_HR
    , PRNMNT_USE_END_YMD
    , PRNMNT_USE_END_HR
    , RCPT_UNT_TASKWK_SE_CD
    , CLR_NO
    , RCPT_INST_NO
    , RQST_TRPR_INFO_NO
    , CASE_MNG_NO
    , CASE_MNG_ODRNO
    , RQST_APLY_YN
    , RQST_DTL_CN
    , LINK_TYPE_SE_CD
    , ATFINO
    , FRST_RGTR_ID
    , FRST_REG_DT
    , LAST_MDFR_ID
    , LAST_MDFCN_DT
) VALUES (
    SYSDATE
    , #{SRVC_PVSN_RQST_NO}
    , #{DATAA_CHG_SE_CD}
    , #{RESRCE_NO}
    , #{HPE_SRVC_YN}
    , (SELECT
        D.CMMNS_CD_VALUE
        FROM SAB200 C /* 메뉴 */, SAC100 D /* 공통코드 값 */
        WHERE 
            C.MENU_NO = (
             SELECT E.MENU_NO 
                FROM SAB200 E
                WHERE E.MENU_LEVELA_NO = 1
                START WITH E.MENU_NO = #{MENU_NO}
                CONNECT BY PRIOR E.UP_MENU_NO = E.MENU_NO
            )
            AND D.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD'
            AND D.CMMNS_CD_VALUE_NM = C.MENU_NM)
    , #{RCPT_RQST_COURS_SE_CD}
    , #{RQST_YMD}
    , #{CLINT_NO}
    , #{RQST_INST_NO}
    , #{RQST_CS_CN}
    , #{PRNMNT_USE_BGNG_YMD}
    , #{PRNMNT_USE_BGNG_HR}
    , #{PRNMNT_USE_END_YMD}
    , #{PRNMNT_USE_END_HR}
    , #{RCPT_UNT_TASKWK_SE_CD}
    , #{CLR_NO}
    , #{RCPT_INST_NO}
    , #{RQST_TRPR_INFO_NO}
    , #{CASE_MNG_NO}
    , #{CASE_MNG_ODRNO}
    , #{RQST_APLY_YN}
    , #{RQST_DTL_CN}
    , #{LINK_TYPE_SE_CD}
    , #{ATFINO}
    , #{USER_ID}
    , SYSDATE
    , #{USER_ID}
    , SYSDATE
)

