mapper.insert:
INSERT INTO SEA200 (
    TRPR_INFO_NO
    , INDV_IDNTFC_NO
    , UNT_TASKWK_SE_CD
    , TRPR_NM_ENCPT
    , TRPR_BRTH_YMD
