SELECT T99.* FROM ( SELECT /*isry.itgcm.linkmng.outsd.mapper.LinkTrprRqstMapper.selectLinkTrprRcptList(연계접수목록)*/ A.SRVC_PVSN_RQST_NO , A.RESRCE_NO , A.HPE_SRVC_YN , A.RQST_UNT_TASKWK_SE_CD , A.RQST_UNT_TASKWK_SE_NM , A.RCPT_RQST_COURS_SE_CD , A.RCPT_RQST_COURS_SE_NM , A.RQST_YMD , A.CLINT_NO , A.CLINT_NM , A.RQST_CS_CN , A.PRNMNT_USE_BGNG_YMD , A.PRNMNT_USE_BGNG_HR , A.PRNMNT_USE_END_YMD , A.PRNMNT_USE_END_HR , A.RCPT_UNT_TASKWK_SE_CD , A.RCPT_UNT_TASKWK_SE_NM , A.CLR_NO , A.CLR_NM , A.RCPT_INST_NO , A.RCPT_INST_NM , A.RQST_TRPR_INFO_NO , A.RQST_TRPR_INFO_NM , A.INDV_IDNTFC_NO , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , A.RQST_APLY_YN , A.RQST_DTL_CN , A.LINK_TYPE_SE_CD , A.LINK_TYPE_SE_NM , A.ATFINO , A.TRMN_PRCS_YN , A.RQST_INST_NO , A.RQST_INST_NM , B.RCPT_SE_CD , B.RCPT_TRPR_INFO_NO , B.RCPT_DTL_CN , B.RCPT_YMD , (SELECT RCPT_YMD FROM SEB421 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND RCPT_SE_CD = B.RCPT_SE_CD AND RCPT_UNT_TASKWK_SE_CD = B.RCPT_UNT_TASKWK_SE_CD AND MDFCN_DT = (SELECT MIN(MDFCN_DT) FROM SEB421 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND RCPT_SE_CD = B.RCPT_SE_CD AND RCPT_UNT_TASKWK_SE_CD = B.RCPT_UNT_TASKWK_SE_CD)) AS FIRST_RCPT_YMD , ROWNUM AS SEQ FROM ( SELECT A.SRVC_PVSN_RQST_NO , A.RESRCE_NO , A.HPE_SRVC_YN , A.RQST_UNT_TASKWK_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RQST_UNT_TASKWK_SE_CD' AND D.CMMNS_CD_VALUE = A.RQST_UNT_TASKWK_SE_CD ) AS RQST_UNT_TASKWK_SE_NM , A.RCPT_RQST_COURS_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND D.CMMNS_CD_VALUE = A.RCPT_RQST_COURS_SE_CD ) AS RCPT_RQST_COURS_SE_NM , A.RQST_YMD , A.CLINT_NO , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 C WHERE C.ENFSN_NO = A.CLINT_NO) AS CLINT_NM , A.RQST_CS_CN , A.PRNMNT_USE_BGNG_YMD , A.PRNMNT_USE_BGNG_HR , A.PRNMNT_USE_END_YMD , A.PRNMNT_USE_END_HR , A.RCPT_UNT_TASKWK_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'RCPT_UNT_TASKWK_SE_CD' AND D.CMMNS_CD_VALUE = A.RCPT_UNT_TASKWK_SE_CD ) AS RCPT_UNT_TASKWK_SE_NM , A.CLR_NO , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 C WHERE C.ENFSN_NO = A.CLR_NO) AS CLR_NM , A.RCPT_INST_NO , (SELECT C.INST_NM FROM SAA000 C WHERE A.RCPT_INST_NO = C.INST_NO) AS RCPT_INST_NM , A.RQST_TRPR_INFO_NO , (SELECT C##RG.DEC_B64(D.TRPR_NM_ENCPT) FROM SEA200 D WHERE D.TRPR_INFO_NO = A.RQST_TRPR_INFO_NO) AS RQST_TRPR_INFO_NM , (SELECT D.INDV_IDNTFC_NO FROM SEA200 D WHERE D.TRPR_INFO_NO = A.RQST_TRPR_INFO_NO) AS INDV_IDNTFC_NO , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , A.RQST_APLY_YN , A.RQST_DTL_CN , A.LINK_TYPE_SE_CD , (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D WHERE D.CMMNS_CD_ID = 'LINK_TYPE_SE_CD' AND D.CMMNS_CD_VALUE = A.LINK_TYPE_SE_CD ) AS LINK_TYPE_SE_NM , A.ATFINO , A.TRMN_PRCS_YN , A.RQST_INST_NO , (SELECT C.INST_NM FROM SAA000 C WHERE A.RQST_INST_NO = C.INST_NO) AS RQST_INST_NM FROM SEB400 A ) A, SEB420 B WHERE 1 = 1 AND A. SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND B.RCPT_SN = (CASE WHEN B.RCPT_SE_CD = '40' THEN (SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO AND RCPT_UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}) ELSE ((SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = B.SRVC_PVSN_RQST_NO) )END)
ORDER BY A.RQST_YMD DESC ) T99 WHERE 1 = 1
AND T99.SEQ >= #{START_IDX} AND T99.SEQ <= #{LAST_IDX}

