    AND A.RQST_YMD BETWEEN #{PRNMNT_USE_BGNG_YMD} AND #{PRNMNT_USE_END_YMD}




    AND A.RCPT_INST_NM LIKE '%경찰%'




    AND (TO_CHAR(TO_DATE(A.RQST_YMD) + 13, 'YYYYMMDD') < TO_CHAR(SYSDATE, 'YYYYMMDD') AND B.RCPT_SE_CD = '11')

