/* isry.itgcm.linkmng.outsd.mapper.LinkTrprRqstMapper.selectSEB420 */        
SELECT SRVC_PVSN_RQST_NO 
     , MAX(RCPT_SN) AS RCPT_SN
FROM SEB420
WHERE SRVC_PVSN_RQST_NO = #{SRVC_PVSN_RQST_NO}
GROUP BY SRVC_PVSN_RQST_NO

